// Короткие домашние варианты игр. Время указано на одну партию.
export const moods={laugh:'Посмеяться',think:'Пошевелить мозгами',know:'Узнать друг друга',move:'Подвигаться'};
export const games=[
{id:'crocodile',name:'Крокодил',desc:'Когда «это же очевидно!» совсем не очевидно. Объясняйте слова только движениями.',min:4,max:20,time:20,mood:'laugh',equipment:'none',color:'lavender',symbol:'✌',tag:'Хит для компании',level:'Легко начать',needs:'Ничего. Только немного места для показа.',rules:['Разделитесь на две команды. Соперники придумывают слово и тихо говорят его вашему актёру.','У актёра одна минута, чтобы показать слово своей команде. Говорить, писать и указывать на буквы нельзя.','Угадали вовремя — команда получает очко. Затем показывает другая команда.','Сыграйте по пять раундов для каждой команды. Побеждает команда с большим количеством очков.'],tip:'Для первого раунда берите простые слова: пингвин, будильник, пылесос. Сложность повышайте постепенно.'},
{id:'contact',name:'Контакт',desc:'Одно слово, одна буква и заговор тех, кто понял друг друга раньше ведущего.',min:3,max:12,time:15,mood:'think',equipment:'none',color:'green',symbol:'А?',tag:'На одной волне',level:'Нужна смекалка',needs:'Ничего. Для начала выбирайте обычные существительные.',rules:['Ведущий загадывает слово и называет первую букву, например «К». Остальные пытаются раскрыть слово.','Любой игрок даёт косвенную подсказку к другому слову на «К»: «Это мурлычет». Само слово не произносит.','Кто понял подсказку, говорит «Контакт!». Ведущий может сорвать контакт, назвав правильное слово: «Кот».','Если ведущий не успел, два игрока считают «три, два, один» и одновременно называют слово. Совпало — ведущий открывает следующую букву своего слова.','Теперь подсказки должны подходить ко всем открытым буквам. Продолжайте, пока не угадаете слово ведущего.'],tip:'Заранее договоритесь не использовать имена и редкие термины. Это домашний вариант с отсчётом вместо строгого таймера.'},
{id:'two-truths',name:'Две правды и ложь',desc:'Узнайте, кто прыгал с парашютом, а кто просто очень убедительно рассказывает.',min:3,max:12,time:15,mood:'know',equipment:'none',color:'peach',symbol:'?!',tag:'Для знакомства',level:'Легко начать',needs:'По три истории о себе — две настоящие и одна выдуманная.',rules:['Каждый придумывает три коротких утверждения о себе: два правдивых и одно ложное. Порядок любой.','Первый игрок произносит все три утверждения. Остальные могут задать ему по одному вопросу.','По сигналу каждый показывает пальцами номер предполагаемой лжи.','Автор раскрывает ответ и при желании рассказывает историю. Передайте ход следующему.'],tip:'Выбирайте темы, которыми комфортно делиться. Любой вопрос можно пропустить без объяснения.'},
{id:'hat',name:'Шляпа',desc:'Угадывайте персонажей и предметы из шляпы: сначала по объяснению, затем по одному слову и жестам.',min:4,max:20,time:30,mood:'laugh',equipment:'paper',color:'yellow',symbol:'★',tag:'Три раунда веселья',level:'Командная',needs:'Бумага, ручки и миска или шляпа. Каждый пишет на отдельных листочках пять персонажей или предметов, знакомых всем: например, Шрек, Гарри Поттер, чайник, зонт, велосипед.',rules:['Разделитесь на команды и сложите листочки в общую ёмкость. Ведущий игрок вытягивает слова и объясняет своей команде в течение минуты. Однокоренные слова запрещены.','За каждое угаданное слово — очко. Неугаданное верните обратно. Передавайте ход между командами, пока слова не кончатся.','Верните все листочки в шляпу. Во втором раунде каждое слово разрешается объяснять только одним словом.','В третьем раунде используйте только жесты. Сложите очки всех раундов и определите победителя.'],tip:'Выберите тему: персонажи, предметы или всё вперемешку. Объясняя персонажа, не называйте его имя; объясняя предмет, не используйте однокоренные слова. В каждом раунде угадывайте одни и те же листочки. Если времени мало, сыграйте только первый раунд.'},
{id:'associations',name:'Цепочка ассоциаций',desc:'От лимона до космонавта за пять ходов. Посмотрим, куда вас заведут ассоциации.',min:2,max:20,time:10,mood:'think',equipment:'none',color:'blue',symbol:'↝',tag:'Даже для двоих',level:'Легко начать',needs:'Ничего. Можно играть сидя за столом или в дороге.',rules:['Первый игрок произносит любое слово. Следующий быстро называет ассоциацию к нему.','На ответ — пять секунд. Повторять уже звучавшие слова нельзя.','Если связь непонятна, игрок кратко объясняет её. Принимайте необычные, но понятные связи.','При паузе или повторе начните новую цепочку. Общая цель — дойти до двадцати слов подряд.'],tip:'Попробуйте тематический раунд: путешествия, кино или еда. Здесь можно играть без выбывания.'},
{id:'mirror',name:'Зеркало',desc:'Один двигается, второй становится его отражением. Кто первым собьётся и засмеётся?',min:2,max:20,time:10,mood:'move',equipment:'none',color:'pink',symbol:'↔',tag:'Размяться',level:'Без соревнования',needs:'Немного свободного места. Движения можно выполнять сидя.',rules:['Разбейтесь на пары и встаньте или сядьте друг напротив друга. Один будет ведущим, второй — зеркалом.','В течение минуты ведущий медленно двигает руками и меняет выражение лица. Зеркало повторяет движения.','Поменяйтесь ролями. Не делайте резких движений и не касайтесь партнёра.','В последнем раунде попробуйте двигаться без назначенного ведущего, подстраиваясь друг под друга.'],tip:'Ограничьтесь комфортной амплитудой движений. Главная цель — синхронность, а не сложные позы.'},
{id:'twenty',name:'20 вопросов',desc:'Задумали предмет? У компании есть двадцать попыток, чтобы добраться до ответа.',min:2,max:12,time:10,mood:'think',equipment:'none',color:'yellow',symbol:'20',tag:'Компактная игра',level:'На логику',needs:'Ничего. Перед началом выберите категорию: предметы, животные или места.',rules:['Один игрок загадывает известный всем объект из выбранной категории.','Остальные по очереди задают вопросы, на которые можно ответить «да» или «нет». При необходимости разрешено «не знаю».','Любая попытка назвать ответ тоже считается вопросом. Всего у команды двадцать вопросов.','Угадали — следующий ведущий тот, кто назвал ответ. Не угадали — ведущий раскрывает его и передаёт ход.'],tip:'Начинайте с широких вопросов: «Это живое?», «Это можно встретить дома?».'},
{id:'story',name:'История по кругу',desc:'Начните с «Однажды в лифте…» и закончите там, куда не доведёт ни один сценарист.',min:3,max:20,time:10,mood:'laugh',equipment:'none',color:'peach',symbol:'…',tag:'Воображение на волю',level:'Без соревнования',needs:'Только готовность подхватить чужую идею.',rules:['Первый игрок начинает историю одним предложением. Например: «Однажды в лифте я встретил говорящий кактус».','Каждый следующий добавляет ровно одно предложение, сохраняя уже случившиеся события.','Нельзя отменять чужие идеи фразами «это был сон» или «ничего этого не было».','Сделайте три круга. На последнем круге постепенно подведите историю к финалу.'],tip:'Договоритесь о жанре: детектив, фантастика или комедия. Можно пропустить ход, если идея не приходит.'},
{id:'categories',name:'Города и не только',desc:'Одна буква, несколько категорий и гонка за самым неожиданным ответом.',min:2,max:12,time:20,mood:'think',equipment:'paper',color:'green',symbol:'АБ',tag:'Бумажная классика',level:'На скорость',needs:'Лист и ручка для каждого. Начертите колонки: город, животное, еда, предмет.',rules:['Выберите букву. Все одновременно заполняют колонки словами на эту букву.','На раунд — две минуты. На каждую категорию нужен один ответ.','Сравните результаты: уникальный подходящий ответ — два очка, совпавший с чьим-то — одно, пустая клетка — ноль.','Проведите пять раундов с разными буквами. Побеждает игрок с наибольшей суммой очков.'],tip:'Для первого раза исключите сложные буквы. Спорные ответы обсудите и примите общим решением.'},
{id:'common',name:'Что у нас общего?',desc:'Найдите неожиданные совпадения. «Все любим пиццу» — только разминка.',min:3,max:16,time:10,mood:'know',equipment:'none',color:'lavender',symbol:'∞',tag:'Растопить лёд',level:'Без соревнования',needs:'Ничего. Для большой компании удобнее разбиться на группы по 3–4 человека.',rules:['За три минуты найдите пять фактов, которые объединяют всех в вашей группе.','Очевидное вроде «мы сейчас здесь» не считается. Ищите привычки, вкусы или общий опыт.','Каждый должен подтвердить совпадение. Не уговаривайте соглашаться ради результата.','Поделитесь самым неожиданным фактом с остальными. Если группа одна, выберите любимую находку.'],tip:'Начните с музыки, еды и увлечений. Личные темы затрагивайте только по желанию.'},
{id:'broken-drawing',name:'Испорченный рисунок',desc:'Фраза превращается в рисунок, рисунок — обратно во фразу. Финал обычно непредсказуем.',min:4,max:12,time:20,mood:'laugh',equipment:'paper',color:'pink',symbol:'✎',tag:'Рисовать не обязательно уметь',level:'Творческая',needs:'По листу и ручке каждому. Листы будут передаваться по кругу.',rules:['Каждый пишет сверху листа короткую фразу и передаёт лист соседу.','Сосед рисует фразу ниже, затем загибает лист так, чтобы текст был скрыт, а рисунок оставался виден.','Следующий описывает рисунок одной фразой и прячет рисунок загибом. Продолжайте чередовать рисунок и текст.','Когда лист вернётся автору, разверните всю цепочку и прочитайте её вслух. На каждый ход давайте минуту.'],tip:'Достаточно человечков из палочек. Чем проще рисунок, тем неожиданнее бывает результат.'},
{id:'rhythm',name:'Поймай ритм',desc:'Хлопок, щелчок, ещё хлопок. Сможете ли вы удержать общий ритм?',min:3,max:20,time:10,mood:'move',equipment:'none',color:'blue',symbol:'♫',tag:'Добавить энергии',level:'Кооперативная',needs:'Место, где негромкие хлопки никому не мешают. Можно играть сидя.',rules:['Первый игрок задаёт короткий ритм из двух хлопков. Все повторяют.','Следующий повторяет ритм и добавляет один звук: хлопок, щелчок или лёгкое постукивание по колену.','Каждый новый игрок повторяет всю последовательность и добавляет один звук.','При ошибке дружно начинайте заново. Попробуйте вместе собрать цепочку из двенадцати звуков.'],tip:'Вместо громких хлопков можно использовать тихие движения рук. Не ускоряйтесь, пока всем не комфортно.'},
{id:'either',name:'Выбирай одно',desc:'Горы или море? Телепорт или машина времени? Выбор простой, обсуждение — не всегда.',min:2,max:20,time:10,mood:'know',equipment:'none',color:'green',symbol:'/ /',tag:'Начать разговор',level:'Легко начать',needs:'Несколько вопросов с двумя вариантами. Их можно придумывать по ходу.',rules:['Игрок предлагает два варианта: «Жить у моря или в горах?».','По отсчёту «три, два, один» каждый показывает один или два пальца.','Желающие объясняют свой выбор. Здесь нет правильных ответов и очков.','Передайте роль автора вопроса следующему. Сыграйте по два вопроса на человека.'],tip:'Ещё идеи: понимать животных или знать все языки; путешествие в прошлое или будущее. Любой вопрос можно пропустить.'},
{id:'word-ban',name:'Запретное слово',desc:'Объясните «кофе», не сказав «напиток», «утро» и «чашка». Сложнее, чем кажется.',min:4,max:20,time:20,mood:'think',equipment:'paper',color:'yellow',symbol:'×',tag:'Найдите другие слова',level:'Командная',needs:'Бумага и ручки. На карточке напишите слово и три запрещённых слова для его объяснения.',rules:['Каждый готовит по три карточки. Перемешайте их и разделитесь на команды.','Игрок вытягивает карточку и за минуту объясняет основное слово своей команде. Запрещены три слова на карточке, их формы и однокоренные к ответу.','Угаданное слово приносит очко. За запрещённое слово карточка уходит в сброс без очка. За ход можно один раз пропустить карточку.','После пяти ходов каждой команды сравните очки. Проверять ограничения помогает игрок соперников.'],tip:'Пример карточки: «велосипед», запреты — «колесо», «педаль», «ехать». Сначала делайте карточки попроще.'},
{id:'count',name:'Считаем вместе',desc:'Досчитайте до двадцати всей компанией. Без очереди. Без сговора. Без одновременных ответов.',min:3,max:20,time:10,mood:'think',equipment:'none',color:'lavender',symbol:'1·2',tag:'Командная связь',level:'Кооперативная',needs:'Ничего. Уберите таймеры и другие подсказки.',rules:['Цель — вслух досчитать от одного до двадцати. Любой может назвать следующее число.','Нельзя заранее назначать очередь, подавать сигналы или произносить два числа подряд одному игроку.','Если два человека заговорили одновременно, вся компания начинает с единицы.','Дайте себе пять минут на попытки. Если дошли до двадцати, попробуйте ещё раз с другим темпом.'],tip:'Для трёх игроков можно начать с десяти. Не превращайте паузы в предсказуемый порядок.'},
{id:'freeze',name:'Замри в кадре',desc:'За пять секунд превратите компанию в оркестр, космический экипаж или очередь за кофе.',min:3,max:20,time:10,mood:'move',equipment:'none',color:'peach',symbol:'▣',tag:'Живые картинки',level:'Творческая',needs:'Немного свободного места. Все позы можно показывать сидя.',rules:['Один игрок становится режиссёром и называет сцену: «оркестр перед концертом», «экипаж на Луне» или «пекарня утром».','За пять секунд остальные выбирают роль и замирают в подходящей позе. Касаться друг друга не нужно.','Режиссёр пытается угадать роль каждого. Затем участники по очереди объясняют свой замысел.','Смените режиссёра и придумайте новую сцену. Сыграйте столько раундов, сколько хочется.'],tip:'Выбирайте комфортные позы без прыжков и баланса. Фотографировать можно только с согласия всех участников.'},

{id:'who-am-i',name:'Кто я?',desc:'У всех на лбу персонаж или предмет. Задавайте вопросы и раскройте собственную тайну.',min:2,max:12,time:20,mood:'think',equipment:'paper',color:'lavender',symbol:'Я?',tag:'Персонажи и предметы',level:'На логику',needs:'Листочки, ручки и способ держать карточку так, чтобы её видели все, кроме угадывающего. Приклеивать ко лбу необязательно.',rules:['Каждый пишет для соседа знакомого персонажа или предмет. Например: Чебурашка, робот-пылесос, Шерлок Холмс.','Передайте карточку так, чтобы игрок не видел своего слова. Остальные должны его видеть.','По очереди задавайте о себе вопросы, на которые можно ответить «да» или «нет». После «да» можно спросить ещё, после «нет» ход переходит дальше.','Попытка назвать ответ считается вопросом. Угадавший помогает остальным. Играйте, пока все не узнают свои слова.'],tip:'Для первой партии выберите одну категорию. Если игроку трудно, после трёх кругов дайте одну подсказку.'},
{id:'no-yes-no',name:'Ни да, ни нет',desc:'Поговорите обо всём на свете, не произнеся два самых привычных слова.',min:2,max:12,time:10,mood:'laugh',equipment:'none',color:'peach',symbol:'ДА?',tag:'Ловушка в разговоре',level:'На внимание',needs:'Ничего. Одна беседа длится минуту.',rules:['Выберите интервьюера и отвечающего. Запрещены слова «да» и «нет», в том числе как отдельные ответы внутри длинной фразы.','Интервьюер минуту задаёт короткие вопросы: «Ты любишь чай?», «Ты сейчас сидишь?».','Отвечающий отвечает по смыслу, заменяя запретные слова: «Конечно», «Не люблю», «Сижу». Молчать весь раунд нельзя.','Произнесли запретное слово — раунд окончен. Поменяйтесь ролями. Удержались минуту — получите очко.'],tip:'Перед началом уточните, что слова «недавно» и «передача» допустимы: запрещены именно отдельные слова.'},
{id:'snowball',name:'Снежный ком',desc:'В чемодане уже кактус, ласты и дракон. Сможете повторить весь список?',min:2,max:20,time:10,mood:'think',equipment:'none',color:'blue',symbol:'+1',tag:'Проверить память',level:'Легко начать',needs:'Ничего. Выберите тему: чемодан, пикник или необычный магазин.',rules:['Первый говорит: «Я беру в путешествие…» и называет предмет.','Следующий повторяет фразу со всеми названными предметами в прежнем порядке и добавляет свой.','Продолжайте по кругу, не записывая список. Повторять предметы нельзя.','При ошибке компания вместе восстанавливает список и начинает новый. Цель — запомнить пятнадцать предметов.'],tip:'Добавляйте предметам смешные признаки: «полосатый чайник» запоминается лучше, чем просто «чайник».'},
{id:'broken-phone',name:'Испорченный телефон',desc:'Отправьте фразу в путешествие по кругу и сравните, что добралось до последнего игрока.',min:4,max:20,time:10,mood:'laugh',equipment:'none',color:'pink',symbol:'…?',tag:'Шёпот по кругу',level:'Легко начать',needs:'Возможность сесть или встать цепочкой так, чтобы не мешать другим.',rules:['Первый придумывает короткую необычную фразу и один раз шепчет её соседу.','Сосед передаёт услышанное следующему. Переспрашивать и повторять нельзя.','Последний произносит получившуюся фразу вслух. Первый раскрывает исходную.','Обсудите превращение и поменяйте первого игрока. Не нужно специально искажать слова.'],tip:'Говорите тихо, но разборчиво, без прикосновений. Если шёпот неудобен участникам, выберите «Испорченный рисунок».'},
{id:'melody',name:'Угадай мелодию',desc:'Напойте знакомый мотив без слов. Кто узнает песню по нескольким нотам?',min:3,max:20,time:20,mood:'laugh',equipment:'none',color:'yellow',symbol:'♪?',tag:'Музыка без колонок',level:'Командная',needs:'Песни, знакомые компании. Включать записи не нужно.',rules:['Разделитесь на команды или играйте каждый за себя. Один участник становится исполнителем.','Исполнитель напевает мелодию без слов в течение тридцати секунд. Текст и название подсказывать нельзя.','Первый правильный ответ приносит одно очко. Если никто не узнал песню, исполнитель раскрывает название.','Передайте роль следующему. После двух кругов сравните очки.'],tip:'Договоритесь о подборке: песни из мультфильмов, кино или знакомые хиты. Красиво петь необязательно.'},
{id:'auction',name:'Аукцион слов',desc:'Назовите десять животных за полминуты. Или двенадцать? Кто предложит больше?',min:3,max:12,time:15,mood:'think',equipment:'none',color:'green',symbol:'↑',tag:'Азарт без ставок',level:'На скорость',needs:'Таймер и несколько тем. Никаких денег или других ставок.',rules:['Выберите тему, например животные, профессии или предметы на кухне.','Первый заявляет, сколько разных ответов назовёт за тридцать секунд. Следующие повышают число или пасуют.','Когда остальные спасовали, участник с последней заявкой запускает таймер и перечисляет ответы. Повторы не считаются.','Выполнил заявку — получает очко. Не выполнил — никто не получает очков. Смените тему и сыграйте ещё пять раундов.'],tip:'Не выбирайте слишком узкие темы. Заранее договоритесь, какие ответы считаются разными.'},
{id:'reverse',name:'Слово наоборот',desc:'«Ток» — это кот, а «номил» — лимон? Прислушайтесь к словам с другой стороны.',min:2,max:12,time:10,mood:'think',equipment:'paper',color:'blue',symbol:'←А',tag:'Перевернуть привычное',level:'На смекалку',needs:'Бумага и ручка ведущему, чтобы без ошибок записать слово в обратном порядке.',rules:['Ведущий выбирает знакомое слово из четырёх–семи букв и записывает его наоборот.','Он медленно читает получившуюся последовательность букв. Остальные пытаются восстановить слово.','Первый правильный ответ приносит очко. Если за тридцать секунд никто не угадал, ведущий показывает запись.','После каждого слова меняйте ведущего. Сыграйте по два слова на каждого участника.'],tip:'Разминка: «апялш» — шляпа, «тноз» — зонт. Используйте обычное написание, а не обратную аудиозапись.'},
{id:'alibi',name:'Алиби',desc:'Двое уверяют, что провели вечер вместе. Проверим, совпадут ли детали их истории.',min:4,max:12,time:20,mood:'laugh',equipment:'none',color:'peach',symbol:'!?',tag:'Проверка легенды',level:'На воображение',needs:'Два добровольца и возможность отвечать по одному, чтобы второй не слышал.',rules:['Два игрока за две минуты придумывают общий вымышленный вечер: где были, что ели, кого встретили.','Один остаётся отвечать, второй ненадолго отходит так, чтобы не слышать разговор. Остальные задают пять конкретных вопросов и запоминают ответы.','Позовите второго и задайте те же вопросы в том же порядке. Первый больше не подсказывает.','За каждое совпадение пара получает очко. Выберите новую пару и придумайте другую историю.'],tip:'Задавайте вопросы о деталях вымышленной истории, а не о личной жизни. При желании записывайте ответы на бумаге.'}

];
export function filterGames({players=4,duration=0,equipment='any',mood='all',savedOnly=false,saved=[],query=''}={}){const normalize=s=>s.toLocaleLowerCase('ru').replaceAll('ё','е').trim();const words=normalize(query).split(/\s+/).filter(Boolean);return games.filter(g=>words.every(word=>normalize(g.name).includes(word))&&players>=g.min&&players<=g.max&&(!duration||g.time<=duration)&&(equipment==='any'||g.equipment==='none'||g.equipment===equipment)&&(mood==='all'||g.mood===mood)&&(!savedOnly||saved.includes(g.id)));}
